/* Signature Kazakh Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Aynurgul": "From aynur (moonlight) + gul (flower).", "Nuraigerim": "From nur (light) + aigerim.", "Timurnur": "From timur (iron) + nur (light): 'iron light'.", "Gulnaray": "From gulnara + ay (moon).", "Seriknur": "From serik (companion) + nur.", "Aybarsgul": "From aybars (moon leopard) + gul.", "Aynurgulov": "Signature surname in -ov style.", "Timurnuruly": "Signature patronymic-style surname: 'son of Timurnur'.", "Gulnaraykyzy": "Signature patronymic-style surname: 'daughter of Gulnaray'.", "Seriknurov": "Signature surname in -ov style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Aynurgul';
console.log(lookup(q));

